using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DrawAdditionalDieOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/DrawAdditionalDieOmenData")]
public class DrawAdditionalDieOmenData : OnStartOfBattleOmenData
{
	[Header("DrawAdditionalDie Omen")]
	[SerializeField]
	protected int additionalDieAmount = 1;

	private Func<int> drawAdditionalDieOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		InitializeNoStartOfBattle(omenInstance, additionalDieAmount, ref drawAdditionalDieOmenAction);
	}

	public void InitializeNoStartOfBattle(OmenInstance omenInstance, int externalAdditionalDieAmount, ref Func<int> externalOmenAction)
	{
		externalOmenAction = () => externalAdditionalDieAmount;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.DrawAdditionalDieOmenActions.Add(externalOmenAction);
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDrawDiceAmountWithOmensModifiers();
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		OmenRemovedNoStartOfBattle(ref drawAdditionalDieOmenAction);
	}

	public void OmenRemovedNoStartOfBattle(ref Func<int> externalOmenAction)
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.DrawAdditionalDieOmenActions.Remove(externalOmenAction);
	}

	public override string OmenConvertedDescription()
	{
		string text = base.OmenConvertedDescription();
		if (additionalDieAmount > 0)
		{
			return GetDrawAdditionalDieDescription(additionalDieAmount) + "\n" + text;
		}
		return text + "\n" + GetDrawAdditionalDieDescription(additionalDieAmount);
	}

	public string GetDrawAdditionalDieDescription(int externalAdditionalDieAmount)
	{
		return Smart.Format((externalAdditionalDieAmount > 0) ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAddDie() : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSubtractDie(), Mathf.Abs(externalAdditionalDieAmount));
	}
}
